import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import api from "../../api/axios";

const TicketDetail = () => {
  const { id } = useParams();
  const [ticket, setTicket] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const isAdmin = localStorage.getItem("is_staff") === "true";

  useEffect(() => {
    setLoading(true);
    api
      .get(`tickets/${id}/`)
      .then((res) => {
        setTicket(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setError("Failed to load ticket details.");
        setLoading(false);
      });
  }, [id]);

  const updateStatus = async (newStatus) => {
    try {
      const res = await api.patch(`tickets/${id}/`, { status: newStatus });
      setTicket(res.data);
    } catch (err) {
      console.error("Status update failed:", err);
    }
  };

  if (loading) return <div style={styles.loading}>Loading ticket details...</div>;
  if (error) return <div style={styles.error}>{error}</div>;
  if (!ticket) return null;

  const getPriorityBadge = (priority) => {
    const p = priority?.toUpperCase() || "";
    if (p === "HIGH") return { bg: "#ff4d4f", text: "High" };
    if (p === "MEDIUM") return { bg: "#faad14", text: "Medium" };
    if (p === "LOW") return { bg: "#52c41a", text: "Low" };
    return { bg: "#d9d9d9", text: priority || "N/A" };
  };

  const getStatusBadge = (status) => {
    const s = status?.toUpperCase() || "";
    switch (s) {
      case "OPEN":
        return { bg: "#1890ff", text: "Open" };
      case "IN_PROGRESS":
        return { bg: "#faad14", text: "In Progress" };
      case "RESOLVED":
        return { bg: "#52c41a", text: "Resolved" };
      case "PARTIALLY_CLOSED":
        return { bg: "#9254de", text: "Partially Closed" };
      default:
        return { bg: "#d9d9d9", text: status || "N/A" };
    }
  };

  const priorityBadge = getPriorityBadge(ticket.priority);
  const statusBadge = getStatusBadge(ticket.status);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <h3 style={styles.title}>Ticket #{id} - {ticket.title}</h3>
          <div style={styles.badges}>
            <span style={{ ...styles.badge, background: priorityBadge.bg }}>
              {priorityBadge.text}
            </span>
            <span style={{ ...styles.badge, background: statusBadge.bg }}>
              {statusBadge.text}
            </span>
          </div>
        </div>

        {/* Details */}
        <div style={styles.details}>
          <p style={styles.description}>{ticket.description}</p>

          {ticket.attachments?.length > 0 ? (
            <div style={styles.attachments}>
              <strong>Attachments:</strong>
              <ul style={styles.attachmentList}>
                {ticket.attachments.map((att, idx) => (
                  <li key={idx}>
                    <a href={att.file || att} target="_blank" rel="noopener noreferrer">
                      {att.name || `Attachment ${idx + 1}`}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ) : (
            <p style={styles.noAttachment}>No attachments</p>
          )}

          {/* Admin-only section */}
          {isAdmin && (
            <>
              <hr style={styles.hr} />
              <div style={styles.adminSection}>
                <h5 style={styles.adminTitle}>Confidential Notes</h5>
                <p style={styles.notes}>
                  {ticket.confidential_notes || "No notes available"}
                </p>

                {ticket.status !== "RESOLVED" && (
                  <button
                    onClick={() => updateStatus("RESOLVED")}
                    style={styles.resolveButton}
                  >
                    Mark as Resolved
                  </button>
                )}
              </div>
            </>
          )}

          {/* Audit Log */}
          <hr style={styles.hr} />
          <h5 style={styles.auditTitle}>Audit Log</h5>
          {ticket.audit_logs?.length > 0 ? (
            <ul style={styles.auditList}>
              {ticket.audit_logs.map((log) => (
                <li key={log.id} style={styles.auditItem}>
                  <span style={styles.auditTime}>
                    {new Date(log.timestamp).toLocaleString()}
                  </span>
                  <span>{log.message}</span>
                </li>
              ))}
            </ul>
          ) : (
            <p style={styles.noLogs}>No audit logs available</p>
          )}
        </div>
      </div>
    </div>
  );
};


const styles = {
  container: {
    padding: "40px 20px",
    maxWidth: "900px",
    margin: "0 auto",
    background: "linear-gradient(to bottom, #f9faff, #ffffff)",
    minHeight: "100vh",
    fontFamily: "Arial, sans-serif",
  },
  card: {
    background: "#ffffff",
    borderRadius: "16px",
    boxShadow: "0 8px 32px rgba(0,0,0,0.1)",
    overflow: "hidden",
    padding: "32px",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    flexWrap: "wrap",
    marginBottom: "24px",
  },
  title: {
    fontSize: "28px",
    fontWeight: "700",
    color: "#4527a0",
    margin: 0,
  },
  badges: {
    display: "flex",
    gap: "12px",
  },
  badge: {
    padding: "8px 16px",
    borderRadius: "24px",
    color: "#ffffff",
    fontSize: "14px",
    fontWeight: "600",
    textTransform: "uppercase",
  },
  details: {
    lineHeight: "1.6",
  },
  description: {
    fontSize: "16px",
    color: "#333",
    marginBottom: "24px",
  },
  attachments: {
    marginBottom: "24px",
  },
  attachmentList: {
    listStyle: "none",
    padding: 0,
    margin: "12px 0 0",
  },
  noAttachment: {
    color: "#888",
    fontStyle: "italic",
  },
  hr: {
    border: "none",
    borderTop: "1px solid #eee",
    margin: "32px 0",
  },
  adminSection: {
    marginBottom: "32px",
  },
  adminTitle: {
    fontSize: "20px",
    color: "#4527a0",
    marginBottom: "12px",
  },
  notes: {
    background: "#f8f9fa",
    padding: "16px",
    borderRadius: "8px",
    border: "1px solid #e0e0e0",
  },
  resolveButton: {
    padding: "12px 24px",
    background: "linear-gradient(135deg, #52c41a, #389e0d)",
    color: "#ffffff",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
    marginTop: "16px",
  },
  auditTitle: {
    fontSize: "20px",
    color: "#4527a0",
    marginBottom: "16px",
  },
  auditList: {
    listStyle: "none",
    padding: 0,
  },
  auditItem: {
    display: "flex",
    gap: "12px",
    marginBottom: "12px",
    padding: "12px",
    background: "#f8f9fa",
    borderRadius: "8px",
  },
  auditTime: {
    fontWeight: "bold",
    color: "#666",
    whiteSpace: "nowrap",
  },
  noLogs: {
    color: "#888",
    fontStyle: "italic",
  },
  loading: {
    textAlign: "center",
    fontSize: "24px",
    color: "#4527a0",
    padding: "100px 0",
  },
  error: {
    textAlign: "center",
    fontSize: "20px",
    color: "#ff4d4f",
    padding: "100px 0",
  },
};

export default TicketDetail;
